using UnityEditor; using UnityEngine; using UnityEngine.InputSystem;
public static class VR147M7InputAudit { public static void Run(){ var a=AssetDatabase.LoadAssetAtPath<InputActionAsset>("Assets/InputSystem_Actions.inputactions"); if(a==null)throw new System.Exception("Input asset missing"); var m=a.FindActionMap("Player",false); if(m==null)throw new System.Exception("Player map missing"); Check(m,"Attack","<XRController>/{PrimaryAction}"); Check(m,"Interact","<XRController>/trigger"); Debug.Log("[M7 INPUT AUDIT PASS] XR Attack/Interact bindings verified."); }
static void Check(InputActionMap m,string n,string p){var a=m.FindAction(n,false);if(a==null)throw new System.Exception("Missing action "+n);foreach(var b in a.bindings)if(b.path==p)return;throw new System.Exception("Missing binding "+n+" -> "+p);}}
